import { retry, retryWhen, delay, scan, tap } from 'rxjs/operators';

// Simple retry — 3 attempts with 1 second delay
this.http.get('/api/data').pipe(
  retry({ count: 3, delay: 1000 })
).subscribe();

// Exponential backoff retry
this.http.get('/api/data').pipe(
  retryWhen(errors =>
    errors.pipe(
      scan((retryCount, error) => {
        if (retryCount >= 3) throw error; // Give up after 3
        return retryCount + 1;
      }, 0),
      tap(count => console.log(`Retry attempt ${count}`)),
      delay(count => count * 2000)  // 2s, 4s, 6s
    )
  )
).subscribe();

