@Injectable({ providedIn: 'root' })
export class CartService {
  // State
  private cartItems = signal<CartItem[]>([]);

  // Read-only signals (selectors)
  readonly items = this.cartItems.asReadonly();
  readonly totalItems = computed(() => this.cartItems().length);
  readonly totalPrice = computed(() =>
    this.cartItems().reduce((sum, item) => sum + item.price * item.qty, 0)
  );

  // Actions
  addItem(item: CartItem) {
    this.cartItems.update(items => [...items, item]);
  }

  removeItem(id: number) {
    this.cartItems.update(items => items.filter(i => i.id !== id));
  }

  updateQuantity(id: number, qty: number) {
    this.cartItems.update(items =>
      items.map(i => i.id === id ? { ...i, qty } : i)
    );
  }

  clearCart() {
    this.cartItems.set([]);
  }
}

